solution.solution.cpp:
#include <cctype>
#include <map>
#include <string>

class Loop
{
public:
    explicit Loop(std::size_t maxQueued) : limit{ maxQueued } {}

    int accept() { connections[next] = {}; return next++; }

    void readable(int id, const std::string& bytes)
    {
        const auto it{ connections.find(id) };
        if (it == connections.end() || it->second.closing) return;
        Connection& c{ it->second };
        c.input += bytes;
        for (std::size_t end{ c.input.find('\n') }; end != std::string::npos; end = c.input.find('\n'))
        {
            std::string line{ c.input.substr(0, end) };
            c.input.erase(0, end + 1);
            if (!line.empty() && line.back() == '\r') line.pop_back();
            if (line == "QUIT")
            {
                c.closing = true;
                c.input.clear();
                if (c.output.empty()) connections.erase(it);
                return;
            }
            for (char& ch : line) ch = static_cast<char>(std::toupper(static_cast<unsigned char>(ch)));
            if (c.output.size() + line.size() + 1 > limit) { connections.erase(it); return; }
            c.output += line + "\n";
        }
    }

    std::string writable(int id, std::size_t capacity)
    {
        const auto it{ connections.find(id) };
        if (it == connections.end()) return "";
        Connection& c{ it->second };
        std::string sent{ c.output.substr(0, capacity) };
        c.output.erase(0, sent.size());
        if (c.closing && c.output.empty()) connections.erase(it);
        return sent;
    }

    bool wantsWrite(int id) const { const auto it{ connections.find(id) }; return it != connections.end() && !it->second.output.empty(); }
    bool isOpen(int id) const { return connections.count(id) > 0; }
    std::size_t queued(int id) const { const auto it{ connections.find(id) }; return it == connections.end() ? 0 : it->second.output.size(); }

private:
    struct Connection { std::string input, output; bool closing{ false }; };
    std::map<int, Connection> connections;
    std::size_t limit;
    int next{ 1 };
};

unitTests:
TEST("lines in pieces, replies in pieces") {
    Loop loop{ 1024 };
    const int a{ loop.accept() };
    loop.readable(a, "hel");
    CHECK(!loop.wantsWrite(a));
    loop.readable(a, "lo\r\nworld\n");
    CHECK(loop.wantsWrite(a));
    CHECK_EQ(loop.writable(a, 4), std::string("HELL"));
    CHECK_EQ(loop.writable(a, 100), std::string("O\nWORLD\n"));
    CHECK(!loop.wantsWrite(a));
}
TEST("connections are independent") {
    Loop loop{ 1024 };
    const int a{ loop.accept() }, b{ loop.accept() };
    loop.readable(a, "from a\n");
    loop.readable(b, "from b\n");
    CHECK_EQ(loop.writable(b, 100), std::string("FROM B\n"));
    CHECK_EQ(loop.queued(a), 7u);
}
TEST("quit after the replies are written") {
    Loop loop{ 1024 };
    const int a{ loop.accept() };
    loop.readable(a, "bye\nQUIT\nignored\n");
    CHECK(loop.isOpen(a));
    CHECK_EQ(loop.writable(a, 2), std::string("BY"));
    CHECK(loop.isOpen(a));
    CHECK_EQ(loop.writable(a, 100), std::string("E\n"));
    CHECK(!loop.isOpen(a));
    CHECK_EQ(loop.writable(a, 100), std::string(""));
    const int b{ loop.accept() };
    loop.readable(b, "QUIT\r\n");
    CHECK(!loop.isOpen(b));
}
TEST("a client that never reads is dropped") {
    Loop loop{ 16 };
    const int a{ loop.accept() };
    loop.readable(a, "0123456\n");
    loop.readable(a, "0123456\n");
    CHECK(loop.isOpen(a));
    loop.readable(a, "x\n");
    CHECK(!loop.isOpen(a));
    CHECK_EQ(loop.queued(a), 0u);
}

